from pathlib import Path
import struct, re, json
b=Path('/app/trunc.db').read_bytes()

def getvar(buf, off):
    v=0
    for i in range(9):
        if off+i >= len(buf): raise EOFError('varint beyond EOF')
        c=buf[off+i]
        if i==8:
            return (v<<8)|c, off+i+1
        v=(v<<7)|(c&0x7f)
        if not (c&0x80):
            return v, off+i+1
    raise ValueError('bad varint')

def serial_len(t):
    return {0:0,1:1,2:2,3:3,4:4,5:6,6:8,7:8,8:0,9:0}.get(t, (t-12)//2 if t>=12 else None)

def decode_val(t, data):
    if t==0: return None
    if t==8: return 0
    if t==9: return 1
    if 1 <= t <= 6: return int.from_bytes(data, 'big', signed=True)
    if t==7: return struct.unpack('>d', data)[0]
    if t>=13 and t%2: return data.decode('utf-8','replace')
    if t>=12 and not (t%2): return data.hex()
    return data.hex()

def parse_cell(off):
    payload, o=getvar(b,off)
    rowid, o=getvar(b,o)
    payload_start=o
    hsz, ho=getvar(b,o)
    if hsz < 1 or payload_start+payload > len(b):
        raise ValueError('invalid payload boundaries')
    types=[]
    while ho < payload_start+hsz:
        t, ho=getvar(b,ho)
        types.append(t)
    if ho != payload_start+hsz:
        raise ValueError('header mismatch')
    dataoff=payload_start+hsz
    vals=[]
    for t in types:
        l=serial_len(t)
        if l is None: raise ValueError(f'bad serial type {t}')
        vals.append(decode_val(t, b[dataoff:dataoff+l]))
        dataoff += l
    if dataoff != payload_start+payload:
        raise ValueError('payload length mismatch')
    return rowid, vals

# Parse declared cells from first page, which is already a table leaf page.
if b[0] != 13:
    raise SystemExit(f'Expected raw SQLite table leaf page at offset 0, got {b[0]!r}')
ncell=int.from_bytes(b[3:5],'big')
ptrs=[int.from_bytes(b[8+2*i:10+2*i],'big') for i in range(ncell)]
rows=[]
for off in ptrs:
    rowid, vals = parse_cell(off)
    # observed layout: [id/null-placeholder, word, value]
    if len(vals) >= 3 and isinstance(vals[1], str) and vals[1].startswith('testword'):
        rows.append({'rowid': rowid, 'word': vals[1], 'value': vals[2], 'cell_offset': off})
print(json.dumps(rows, indent=2, ensure_ascii=False))
print('declared_cells', ncell, 'recovered_rows', len(rows))
# independent text scan for possible words not captured by cell pointers
words=sorted(set(m.group(0).decode() for m in re.finditer(rb'testword[0-9A-Za-z_\-]*', b)))
print('word_scan_count', len(words), words)
